tool_calls.arguments:
{"code": "
# Let me try to find the MCP settings
import os, glob
for p in glob.glob('/tmp/**/settings*.json', recursive=True):
    print(p)
    try:
        with open(p) as f:
            content = f.read()
            if 'nethack' in content.lower() or 'mcp' in content.lower():
                print(content[:1000])
                print('---')
    except:
        pass
"}

