# Create a helper function to call MCP tools directly via httpx
import httpx
import json

MCP_URL = "http://127.0.0.1:46367/mcp"
MCP_HEADERS = {"Content-Type": "application/json", "Accept": "application/json"}

async def mcp_call(tool_name, arguments=None, timeout=120):
    """Call an MCP tool directly via httpx, bypassing the MCP SDK."""
    if arguments is None:
        arguments = {}
    async with httpx.AsyncClient(timeout=timeout) as client:
        # Initialize
        resp = await client.post(MCP_URL, json={
            "jsonrpc": "2.0", "id": 1, "method": "initialize",
            "params": {"protocolVersion": "2024-11-05", "capabilities": {},
                       "clientInfo": {"name": "agent", "version": "1.0"}}
        }, headers=MCP_HEADERS)
        sid = resp.headers.get("mcp-session-id")
        h = dict(MCP_HEADERS)
        if sid:
            h["mcp-session-id"] = sid

        # Send initialized notification
        await client.post(MCP_URL, json={
            "jsonrpc": "2.0", "method": "notifications/initialized"
        }, headers=h)

        # Call the tool
        resp2 = await client.post(MCP_URL, json={
            "jsonrpc": "2.0", "id": 2, "method": "tools/call",
            "params": {"name": tool_name, "arguments": arguments}
        }, headers=h)

        data = resp2.json()
        if "error" in data:
            return f"ERROR: {data['error']}"
        result = data.get("result", {})
        content = result.get("content", [])
        text_parts = [c.get("text", "") for c in content if c.get("type") == "text"]
        return "\n".join(text_parts)

# Test it - reveal the full map
result = await mcp_call("reveal", {"x1": 0, "y1": 0, "x2": 78, "y2": 20})
print(result)
"}

