async def descend_level(max_explores=15):
    """Explore the current level and try to reach the stairs down."""
    for i in range(max_explores):
        # Reveal and find stairs
        rows, sd, su, mons, items = await reveal_and_find()

        if sd:
            # Try to move to stairs down
            result = await mcp_call("np_move_to", {"x": sd[0], "y": sd[1]})

            # Check if we reached the stairs
            for line in result.split('\n'):
                if 'Pos:' in line:
                    pos_match = line.strip()
                    if f'Pos: ({sd[0]},{sd[1]})' in pos_match or f'Pos: ({sd[0]}, {sd[1]})' in pos_match:
                        # We're at the stairs! Descend!
                        print(f"  Reached stairs at {sd}, descending!")
                        descend_result = await mcp_call("np_down")
                        # Check if we descended
                        for dl in descend_result.split('\n'):
                            if 'Dlvl:' in dl:
                                print(f"  {dl.strip()}")
                            if 'Pos:' in dl:
                                print(f"  {dl.strip()}")
                        return descend_result
                    else:
                        print(f"  Move attempt {i+1}: {pos_match}")

            # If move failed or didn't reach stairs, explore more
            if 'No valid path' in result:
                print(f"  No path to stairs {sd}, exploring...")

        # Check for danger
        if 'low' in result.lower() and 'health' in result.lower():
            print("  HEALTH LOW - stopping!")
            print(result[:500])
            return result

        # Explore
        exp_result = await mcp_call("np_explore_level")
        for line in exp_result.split('\n'):
            if 'Pos:' in line:
                print(f"  Explore {i+1}: {line.strip()}")
            if 'Dlvl:' in line:
                print(f"  {line.strip()}")

    # Final attempt to reach stairs
    rows, sd, su, mons, items = await reveal_and_find()
    if sd:
        result = await mcp_call("np_move_to", {"x": sd[0], "y": sd[1]})
        if 'completed' in result:
            print(f"  Finally reached stairs at {sd}!")
            descend_result = await mcp_call("np_down")
            return descend_result

    print("  Could not reach stairs after max explores")
    return None

